import java.util.*;

public class Main {

    static class McfGraphIntCost {
        private int n;
        private List<int[]> pos;
        private List<List<Edge>> g;

        public McfGraphIntCost(int n) {
            this.n = n;
            this.pos = new ArrayList<>();
            this.g = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
        }

        public int addEdge(int from_, int to, int cap, int cost) {
            int m = pos.size();
            pos.add(new int[]{from_, g.get(from_).size()});
            g.get(from_).add(new Edge(to, g.get(to).size(), cap, cost));
            g.get(to).add(new Edge(from_, g.get(from_).size() - 1, 0, -cost));
            return m;
        }

        public static class Edge {
            int from_, to, cap, flow, cost;

            public Edge(int from_, int to, int cap, int flow, int cost) {
                this.from_ = from_;
                this.to = to;
                this.cap = cap;
                this.flow = flow;
                this.cost = cost;
            }
        }

        public Edge getEdge(int i) {
            int[] p = pos.get(i);
            Edge _e = g.get(p[0]).get(p[1]);
            Edge _re = g.get(_e.to).get(_e.rev);
            return new Edge(p[0], _e.to, _e.cap + _re.cap, _re.cap, _e.cost);
        }

        public List<Edge> edges() {
            List<Edge> ret = new ArrayList<>();
            for (int i = 0; i < pos.size(); i++) {
                int[] p = pos.get(i);
                Edge _e = g.get(p[0]).get(p[1]);
                Edge _re = g.get(_e.to).get(_e.rev);
                ret.add(new Edge(p[0], _e.to, _e.cap + _re.cap, _re.cap, _e.cost));
            }
            return ret;
        }

        private int[] dist;
        private int[] pv;
        private int[] pe;
        private boolean[] vis;
        private int[] dual;

        private boolean dualRef(int s, int t) {
            dist = new int[n];
            pv = new int[n];
            pe = new int[n];
            vis = new boolean[n];
            for (int i = 0; i < n; i++) {
                dist[i] = Integer.MAX_VALUE;
                pv[i] = -1;
                pe[i] = -1;
            }

            PriorityQueue<int[]> que = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            que.add(new int[]{0, s});
            dist[s] = 0;

            while (!que.isEmpty()) {
                int[] cur = que.poll();
                int v = cur[1];
                if (vis[v]) continue;
                vis[v] = true;
                if (v == t) break;

                for (int i = 0; i < g.get(v).size(); i++) {
                    Edge e = g.get(v).get(i);
                    if (vis[e.to] || e.cap == 0) continue;
                    int cost = e.cost - dual[e.to] + dual[v];
                    if (dist[e.to] > dist[v] + cost) {
                        dist[e.to] = dist[v] + cost;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        que.add(new int[]{dist[e.to], e.to});
                    }
                }
            }

            if (!vis[t]) {
                return false;
            }

            for (int v = 0; v < n; v++) {
                if (!vis[v]) continue;
                dual[v] -= dist[t] - dist[v];
            }

            return true;
        }

        public List<int[]> slope(int s, int t, int flow_limit) {
            dual = new int[n];
            dist = new int[n];
            pv = new int[n];
            pe = new int[n];
            vis = new boolean[n];
            for (int i = 0; i < n; i++) {
                dual[i] = 0;
                dist[i] = Integer.MAX_VALUE;
                pv[i] = -1;
                pe[i] = -1;
            }

            int flow = 0;
            int cost = 0;
            int prevCost = -1;
            List<int[]> result = new ArrayList<>();
            result.add(new int[]{flow, cost});

            while (flow < flow_limit) {
                if (!dualRef(s, t)) {
                    break;
                }
                int c = flow_limit - flow;
                int v = t;
                while (v != s) {
                    c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
                    v = pv[v];
                }
                v = t;
                while (v != s) {
                    Edge e = g.get(pv[v]).get(pe[v]);
                    e.cap -= c;
                    g.get(v).get(e.rev).cap += c;
                    v = pv[v];
                }
                int d = -dual[s];
                flow += c;
                cost += c * d;
                if (prevCost == d) {
                    result.remove(result.size() - 1);
                }
                result.add(new int[]{flow, cost});
                prevCost = cost;
            }
            return result;
        }

        public int[] flow(int s, int t, int flow_limit) {
            List<int[]> res = slope(s, t, flow_limit);
            return res.get(res.size() - 1);
        }

        private static class EdgeInternal {
            int to, rev, cap, cost;

            public EdgeInternal(int to, int rev, int cap, int cost) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cost = cost;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a1 = sc.nextInt();
        int a2 = sc.nextInt();
        int a3 = sc.nextInt();
        int b1 = sc.nextInt();
        int b2 = sc.nextInt();
        int b3 = sc.nextInt();

        McfGraphIntCost g = new McfGraphIntCost(8);
        g.addEdge(0, 1, a1, 0);
        g.addEdge(0, 2, a2, 0);
        g.addEdge(0, 3, a3, 0);
        g.addEdge(4, 7, b1, 0);
        g.addEdge(5, 7, b2, 0);
        g.addEdge(6, 7, b3, 0);
        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                int cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, Integer.MAX_VALUE, cost);
            }
        }

        int[] res = g.flow(0, 7, Integer.MAX_VALUE);
        int ans1 = res[1];

        int ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String[] line1 = br.readLine().trim().split(" ");
        int rock1 = Integer.parseInt(line1[0]);
        int sci1 = Integer.parseInt(line1[1]);
        int paper1 = Integer.parseInt(line1[2]);

        String[] line2 = br.readLine().trim().split(" ");
        int rock2 = Integer.parseInt(line2[0]);
        int sci2 = Integer.parseInt(line2[1]);
        int paper2 = Integer.parseInt(line2[2]);

        int maxResult = maximum(rock1, sci1, paper1, rock2, sci2, paper2);
        int minResult = minimum(rock1, sci1, paper1, rock2, sci2, paper2);

        System.out.println(minResult + " " + maxResult);
    }

    public static int maximum(int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        int ans = Math.min(rock1, sci2) + Math.min(sci1, paper2) + Math.min(paper1, rock2);
        return ans;
    }

    public static int match(int a, int b) {
        if (a == b) return 0;
        else if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) return 1;
        else return -1;
    }

    public static int give(List<int[]> l1, List<int[]> l2) {
        int ans = 0;
        int[] curr1 = null;
        int[] curr2 = null;

        while (!l1.isEmpty() || !l2.isEmpty()) {
            try {
                if (curr1 == null && !l1.isEmpty()) {
                    curr1 = l1.remove(l1.size() - 1);
                }
                if (curr2 == null && !l2.isEmpty()) {
                    curr2 = l2.remove(l2.size() - 1);
                }
            } catch (Exception e) {
                return ans;
            }

            if (curr1 == null || curr2 == null) {
                return ans;
            }

            int common = Math.min(curr1[0], curr2[0]);
            ans += Math.max(0, common * match(curr1[1], curr2[1]));

            if (curr1[0] < curr2[0]) {
                curr2[0] -= curr1[0];
                curr1 = null;
            } else if (curr1[0] > curr2[0]) {
                curr1[0] -= curr2[0];
                curr2 = null;
            } else {
                curr1 = null;
                curr2 = null;
            }
        }

        return ans;
    }

    public static int minimum(int rock1, int sci1, int paper1, int rock2, int sci2, int paper2) {
        List<int[]> l = new ArrayList<>();
        l.add(new int[]{rock1, 1});
        l.add(new int[]{sci1, 2});
        l.add(new int[]{paper1, 3});

        List<List<int[]>> l1 = generatePermutations(l);

        l = new ArrayList<>();
        l.add(new int[]{rock2, 1});
        l.add(new int[]{sci2, 2});
        l.add(new int[]{paper2, 3});

        List<List<int[]>> l2 = generatePermutations(l);

        int ans = Integer.MAX_VALUE;
        for (List<int[]> perm1 : l1) {
            for (List<int[]> perm2 : l2) {
                List<int[]> mylist1 = new ArrayList<>();
                for (int[] arr : perm1) {
                    mylist1.add(new int[]{arr[0], arr[1]});
                }
                List<int[]> mylist2 = new ArrayList<>();
                for (int[] arr : perm2) {
                    mylist2.add(new int[]{arr[0], arr[1]});
                }
                ans = Math.min(ans, give(mylist1, mylist2));
            }
        }

        return ans;
    }

    public static List<List<int[]>> generatePermutations(List<int[]> list) {
        List<List<int[]>> result = new ArrayList<>();
        permute(list, 0, result);
        return result;
    }

    public static void permute(List<int[]> list, int start, List<List<int[]>> result) {
        if (start == list.size()) {
            result.add(new ArrayList<>(list));
            return;
        }

        for (int i = start; i < list.size(); i++) {
            Collections.swap(list, i, start);
            permute(list, start + 1, result);
            Collections.swap(list, start, i);
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = Integer.parseInt(scanner.nextLine().trim());

        String[] line1 = scanner.nextLine().trim().split("\\s+");
        String[] line2 = scanner.nextLine().trim().split("\\s+");

        int[] inputA = new int[3];
        int[] inputB = new int[3];

        for (int i = 0; i < 3; i++) {
            inputA[i] = Integer.parseInt(line1[i]);
            inputB[i] = Integer.parseInt(line2[i]);
        }

        int[] inputA2 = Arrays.copyOf(inputA, 3);
        int[] inputB2 = Arrays.copyOf(inputB, 3);

        System.out.print((n - getLostMaxFast(inputA2, inputB2)) + " " + getWonMaxFast(inputA, inputB));
    }

    private static int getWonMaxFast(int[] inputA, int[] inputB) {
        int[] wins = new int[3];
        for (int i = 0; i < 3; i++) {
            int good = (i + 1) % 3;
            wins[i] = Math.min(inputA[i], inputB[good]);
            inputA[i] -= wins[i];
            inputB[good] -= wins[i];
        }
        return wins[0] + wins[1] + wins[2];
    }

    private static int getLostMaxFast(int[] inputA, int[] inputB) {
        int[][] waysToLose = {{0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2}};

        // Generate all permutations of waysToLose
        List<int[][]> allPermutations = new ArrayList<>();
        permute(waysToLose, 0, allPermutations);

        int maxLost = 0;

        for (int[][] permutation : allPermutations) {
            int[] losts = new int[3];
            int[] inputACopy = Arrays.copyOf(inputA, 3);
            int[] inputBCopy = Arrays.copyOf(inputB, 3);

            for (int[] wayToLose : permutation) {
                int lost_add = Math.min(inputACopy[wayToLose[0]], inputBCopy[wayToLose[1]]);
                inputACopy[wayToLose[0]] -= lost_add;
                inputBCopy[wayToLose[1]] -= lost_add;
                losts[wayToLose[0]] += lost_add;
            }

            int lostSum = losts[0] + losts[1] + losts[2];

            if (lostSum > maxLost) {
                maxLost = lostSum;
            }
        }

        return maxLost;
    }

    private static void permute(int[][] arr, int k, List<int[][]> result) {
        for (int i = k; i < arr.length; i++) {
            int[][] temp = new int[arr.length][2];
            for (int j = 0; j < arr.length; j++) {
                temp[j][0] = arr[j][0];
                temp[j][1] = arr[j][1];
            }

            // Swap
            int[] tempSwap = temp[k];
            temp[k] = temp[i];
            temp[i] = tempSwap;

            if (k == arr.length - 1) {
                result.add(temp);
            } else {
                permute(temp, k + 1, result);
            }
        }
    }
}

