import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int turnNum = Integer.parseInt(scanner.nextLine().trim());
        String[] aliceInput = scanner.nextLine().trim().split(" ");
        String[] bobInput = scanner.nextLine().trim().split(" ");

        List<Integer> aliceChoices = new ArrayList<>();
        List<Integer> bobChoices = new ArrayList<>();

        for (String s : aliceInput) {
            aliceChoices.add(Integer.parseInt(s));
        }
        for (String s : bobInput) {
            bobChoices.add(Integer.parseInt(s));
        }

        // Move first element to the end
        bobChoices.add(bobChoices.remove(0));

        int minWin = 0;
        int maxWin = 0;

        // Calculate maximum number of rounds Alice can win
        for (int i = 0; i < aliceChoices.size(); i++) {
            maxWin += Math.min(aliceChoices.get(i), bobChoices.get(i));
        }

        // Calculate minimum number of rounds Alice can win
        int maximumBob = Collections.max(bobChoices);
        for (int i = 0; i < bobChoices.size(); i++) {
            if (bobChoices.get(i) == maximumBob && bobChoices.get(i) + aliceChoices.get(i) > minWin) {
                minWin = bobChoices.get(i) + aliceChoices.get(i);
            }
        }

        int maximumAlice = Collections.max(aliceChoices);
        for (int i = 0; i < aliceChoices.size(); i++) {
            if (aliceChoices.get(i) == maximumAlice && aliceChoices.get(i) + bobChoices.get(i) > minWin) {
                minWin = aliceChoices.get(i) + bobChoices.get(i);
            }
        }

        minWin = minWin > turnNum ? minWin - turnNum : 0;

        System.out.println(minWin + " " + maxWin);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int round = Integer.parseInt(scanner.nextLine().trim());
        String[] firstpersonInput = scanner.nextLine().trim().split(" ");
        String[] secondpersonInput = scanner.nextLine().trim().split(" ");

        int[] firstperson = new int[3];
        int[] secondperson = new int[3];

        for (int i = 0; i < 3; i++) {
            firstperson[i] = Integer.parseInt(firstpersonInput[i]);
            secondperson[i] = Integer.parseInt(secondpersonInput[i]);
        }

        solve(round, firstperson, secondperson);
    }

    public static void solve(int round, int[] firstperson, int[] secondperson) {
        // find max win
        int win = 0;
        int[] secondpersonCopy = Arrays.copyOf(secondperson, 4);
        secondpersonCopy[3] = secondpersonCopy[0];

        for (int i = 0; i < 3; i++) {
            int findless = Math.min(firstperson[i], secondpersonCopy[i + 1]);
            win += findless;
        }

        // find min win
        int[] secondpersonForMin = new int[4];
        secondpersonForMin[0] = secondperson[2];
        secondpersonForMin[1] = secondperson[0];
        secondpersonForMin[2] = secondperson[1];
        secondpersonForMin[3] = secondperson[2];

        int[] firstpersonCopy = Arrays.copyOf(firstperson, 3);

        for (int i = 0; i < 3; i++) {
            if (firstpersonCopy[i] > 0) {
                int diff = Math.min(firstpersonCopy[i], secondpersonForMin[i]);
                firstpersonCopy[i] -= diff;
                secondpersonForMin[i] -= diff;

                if (firstpersonCopy[i] > 0) {
                    diff = Math.min(firstpersonCopy[i], secondpersonForMin[i + 1]);
                    firstpersonCopy[i] -= diff;
                    secondpersonForMin[i + 1] -= diff;
                }
            }
        }

        int minWin = firstpersonCopy[0] + firstpersonCopy[1] + firstpersonCopy[2];

        System.out.println(minWin + " " + win);
    }
}

