        for (int i = k; i < arr.length; i++) {
            swap(arr, i, k);
            permute(arr, k + 1, result);
            swap(arr, k, i);
        }
        if (k == arr.length - 1) {
            List<Integer> list = new ArrayList<>();
            for (int val : arr) {
                list.add(val);
            }
            result.add(list);
