        for (int i = n - 1; i >= 1; i--) {
            c[i] = (2 * c[i + 1]) % m;
            for (int j = 2; j <= n / i; j++) {
                c[i] = (c[i] + c[i * j] - c[(i + 1) * j]) % m;
                // Ensure non-negative result
                if (c[i] < 0) {
                    c[i] += m;
                }
            }
