import java.util.*;

public class Main {
    private static List<Integer> primes = new ArrayList<>();

    static {
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }
    }

    private static Map<Integer, Integer> factor(int n) {
        Map<Integer, Integer> d = new HashMap<>();
        for (int p : primes) {
            if (p * p > n) {
                break;
            }
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n = n / p;
                    c++;
                }
                d.put(p, c);
            }
        }
        if (n > 1) {
            d.put(n, 1);
        }
        return d;
    }

    private static List<Integer> factors(int n) {
        Map<Integer, Integer> d = factor(n);
        List<Integer> answer = new ArrayList<>();
        answer.add(1);

        for (Map.Entry<Integer, Integer> entry : d.entrySet()) {
            int p = entry.getKey();
            int exp = entry.getValue();
            List<Integer> a2 = new ArrayList<>();

            for (int x : answer) {
                int power = 1;
                for (int i = 0; i <= exp; i++) {
                    a2.add(x * power);
                    power *= p;
                }
            }
            answer = a2;
        }
        return answer;
    }

    private static int process(int n, int m) {
        Map<Integer, Integer> fDict = new HashMap<>();
        fDict.put(0, 0);
        fDict.put(1, 1);
        fDict.put(2, 2);

        for (int i = 3; i <= n; i++) {
            int val = 2 * fDict.get(i - 1);
            List<Integer> facs = factors(i);

            for (int x : facs) {
                if (x >= 2 && x <= i) {
                    val += fDict.get(i / x) - fDict.get((i - 1) / x);
                    val = val % m;
                }
            }
            val = val % m;
            fDict.put(i, val);
        }
        return fDict.get(n);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        System.out.println(process(n, m));
    }
}

