import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        System.out.println(solve(p, k));
    }

    public static long solve(int p, int k) {
        long MOD = 1000000007;
        long num = 0;
        Set<Integer> used = new HashSet<>();

        for (int j = 0; j < p; j++) {
            if (!used.contains(j)) {
                num++;
            }
            int i = j;
            while (!used.contains(i)) {
                used.add(i);
                i = (int) ((long) i * k % p);
            }
        }

        long exponent = num - (k != 1 ? 1 : 0);
        return powMod(p, exponent, MOD);
    }

    public static long powMod(long base, long exp, long mod) {
        if (exp == 0) return 1;
        base %= mod;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
