        for (int i = 0; i < h; i++) {
            if (dir.equals("L")) {
                double mid = (l + r) / 2.0;
                if (n > mid) {
                    answ += cnt_res(b) + 1;
                    l = (l + r) / 2 + 1;
                } else if (n < mid) {
                    r = (l + r) / 2 + (l + r % 2 != 0 ? 1 : 0) - 1;
                    answ += 1;
                    dir = "R";
                }
                b -= 1;
            } else {
                double mid = (l + r) / 2.0;
                if (n < mid) {
                    answ += cnt_res(b) + 1;
                    r = (l + r) / 2 + (l + r % 2 != 0 ? 1 : 0) - 1;
