        sl[0] = 1;
        for (int i = 1; i < 51; i++) {
            sl[i] = sl[i-1] + (1 << i);
        }

        int h = sc.nextInt();
        int n = sc.nextInt();

        List<Integer> nl = new ArrayList<>();
        n += sl[h-1];
        int tn = n;
        nl.add(tn);
        while (tn != 1) {
            tn = tn / 2;
            nl.add(tn);
        }

        int ans = 0;
        int cn = 1;
        boolean cp = false;

        while (cn != n) {
            List<Integer> tnl = new ArrayList<>();
            for (int i = 0; i < h; i++) {
                tnl.add(cn);
                if (!cp) {
                    cn *= 2;
                } else {
                    cn = cn * 2 + 1;
                }
                cp = !cp;
            }
            if (cn == n) {
                ans += h;
                break;
            }

            tnl.add(cn);
            Collections.reverse(tnl);
            boolean found = false;
            for (int i = 1; i <= h; i++) {
                if (nl.get(i).equals(tnl.get(i))) {
                    ans += sl[i-1] + h - i + 1;
                    h = i - 1;
