        int[] a = new int[20];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        List<Integer> b = new ArrayList<>();
        int halfSize1 = n / 2 + n % 2;

        for (int i = 0; i < (1 << halfSize1); i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) == 1) {
                    t += a[j];
                }
                k = k >> 1;
            }
            b.add(t % m);
        }

        Collections.sort(b);

