        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(secondLine[i]);
        }

        List<Long> a1 = new ArrayList<>();
        List<Long> a2 = new ArrayList<>();
        int n1 = n / 2;

        // Generate all subset sums for first half
        generateSums(a, 0, n1, 0, m, a1);

        // Generate all subset sums for second half
        generateSums(a, n1, n, 0, m, a2);

        // Sort and remove duplicates from a1
        Collections.sort(a1);
        List<Long> uniqueA1 = new ArrayList<>();
        for (int i = 0; i < a1.size(); i++) {
            if (i == 0 || !a1.get(i).equals(a1.get(i - 1))) {
                uniqueA1.add(a1.get(i));
            }
        }

        long ans = 0;
        for (long val : a2) {
            long target = m - val;
            int idx = binarySearchFirstGreaterOrEqual(uniqueA1, target);
            if (idx > 0) {
                long currentSum = uniqueA1.get(idx - 1) + val;
                if (currentSum > ans) {
                    ans = currentSum;
                }
            } else if (idx == 0 && !uniqueA1.isEmpty()) {
                long currentSum = uniqueA1.get(0) + val;
                if (currentSum > ans) {
                    ans = currentSum;
                }
            }
        }

        System.out.println(ans);
    }

    private static void generateSums(long[] a, int start, int end, long currentSum, int m, List<Long> result) {
        if (start == end) {
            result.add(currentSum % m);
        } else {
            generateSums(a, start + 1, end, (currentSum + a[start]) % m, m, result);
            generateSums(a, start + 1, end, currentSum, m, result);
        }
    }

    private static int binarySearchFirstGreaterOrEqual(List<Long> list, long target) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid) >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

