        int m = sc.nextInt();

        int[] l = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = sc.nextInt();
        }

        int n1 = n / 2;
        int n2 = n / 2 + n % 2;

        int[] first = new int[n1];
        int[] sec = new int[n2];

        for (int i = 0; i < n1; i++) {
            first[i] = l[i];
        }
        for (int i = 0; i < n2; i++) {
            sec[i] = l[n1 + i];
        }

        int t1 = 1 << n1;
        int t2 = 1 << n2;

        List<Integer> s1 = new ArrayList<>();
        for (int i = 0; i < t1; i++) {
            int now = 0;
            for (int j = 0; j < n1; j++) {
                if ((i & (1 << j)) != 0) {
                    now += first[j];
                }
            }
            s1.add(now % m);
        }

        List<Integer> s2 = new ArrayList<>();
        for (int i = 0; i < t2; i++) {
            int now = 0;
            for (int j = 0; j < n2; j++) {
                if ((i & (1 << j)) != 0) {
                    now += sec[j];
                }
            }
            s2.add(now % m);
        }

        Collections.sort(s1);
        Collections.sort(s2);

        int maxi = 0;

        for (int i : s1) {
            int req = m - i;
            int pair = check(s2, req);
            maxi = Math.max(maxi, (i + pair) % m);
        }

        System.out.println(maxi);
    }

    // largest number less than x in l (l is ascending)
    private static int check(List<Integer> l, int x) {
        int lo = 0;
        int hi = l.size() - 1;
        int ans = 0;

        while (lo <= hi) {
            int mi = (lo + hi) >> 1;
            if (l.get(mi) < x) {
                ans = l.get(mi);
                lo = mi + 1;
            } else {
                hi = mi - 1;
            }
        }

        return ans;
    }
}

