import java.util.*;

public class Main {
    static int mod;
    static Map<Integer, Map<Integer, Integer>>[][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        mod = sc.nextInt();

        memo = new HashMap[n + 1][2];
        for (int i = 0; i <= n; i++) {
            memo[i][0] = new HashMap<>();
            memo[i][1] = new HashMap<>();
        }

        int ans = solve(n, 0, 1) % mod;
        System.out.println(ans);
    }

    public static int solve(int N, int k, int flag) {
        if (memo[N][flag].containsKey(k)) {
            return memo[N][flag].get(k);
        }

        if (N == 1) {
            int res = -1;
            if (flag == 1) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo[N][flag].put(k, res);
            return res;
        }

        int invnum_INF = (N * (N - 1)) / 2;
        if (k < -invnum_INF - 1) {
            int res = solve(N, -invnum_INF - 1, flag);
            memo[N][flag].put(k, res);
            return res;
        }

        if (k >= invnum_INF) {
            memo[N][flag].put(k, 0);
            return 0;
        }

        int res = 0;

        for (int delta = -N + 1; delta < N; delta++) {
            if (flag == 1 && delta > 0) {
                continue;
            }
            int wt = Math.min(N - delta, delta + N);
            res = (res + solve(N - 1, k - delta, (delta == 0 ? 1 : 0) & flag) * wt) % mod;
        }

        memo[N][flag].put(k, res % mod);
        return res % mod;
    }
}

