            long last_ans = 17;
            long ans = 17;
            int size = (n - 1) * (n - 2) / 2 + 1;
            int inv = 1;
            long[][] record = new long[2][size + 1];

            // Initialize record[0][0:4] = [1, 2, 2, 1]
            record[0][0] = 1;
            record[0][1] = 2;
            record[0][2] = 2;
            record[0][3] = 1;

