                int tp_size = m * (m - 1) / 2;
                ans = (m + 1) * last_ans;
                long tp = 0;

                // First loop
                for (int i = 0; i < m; i++) {
                    tp += record[inv ^ 1][i];
                    record[inv][i] = tp % mod;
                }

                // Second loop
                for (int i = m; i <= tp_size / 2; i++) {
                    tp += record[inv ^ 1][i];
                    tp -= record[inv ^ 1][i - m];
                    record[inv][i] = tp % mod;
                }

                // Third loop
                for (int i = 0; i <= tp_size / 2; i++) {
                    record[inv][tp_size - i] = record[inv][i];
                }

                // Calculate total and ans
                long total = 0;
                for (int i = 0; i < tp_size - 1; i++) {
