import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n >= 4 && m >= 4) {
            System.out.println(n * m - (n * m % 2));
        } else {
            if (Math.min(n, m) == 1) {
                int maxVal = Math.max(n, m);
                if (maxVal % 6 == 5) {
                    System.out.println(maxVal / 6 * 6 + 4);
                } else if (maxVal % 6 == 4) {
                    System.out.println(maxVal / 6 * 6 + 2);
                } else {
                    System.out.println(maxVal / 6 * 6);
                }
            } else if (Math.min(n, m) == 2 && Math.max(n, m) == 7) {
                System.out.println(12);
            } else if ((Math.min(n, m) == 2 && Math.max(n, m) >= 4) || (Math.min(n, m) == 3 && Math.max(n, m) >= 4)) {
                System.out.println(n * m - (n * m % 2));
            } else {
                int[][] d = {
                    {0, 0, 0, 2, 4},
                    {0, 0, 4, 8, 10},
                    {0, 0, 8, 12, 14},
                    {0, 0, 0, 16, 20},
                    {0, 0, 0, 0, 24}
                };
                System.out.println(d[Math.min(n, m) - 1][Math.max(n, m) - 1]);
            }
        }
    }
}

