import java.util.Scanner;

public class Solution {
    public void run() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n > m) {
            int temp = n;
            n = m;
            m = temp;
        }

        int res = (n * m) / 2;

        if (n == 1 && ((m + 1) % 6) / 3 != 0) {
            res -= 1;
        } else if (n == 2) {
            if (m == 2) {
                res = 0;
            } else if (m == 3) {
                res = 2;
            } else if (m == 7) {
                res = 6;
            }
        }

        System.out.println(res * 2);
    }

    public static void main(String[] args) {
        new Solution().run();
    }
}

