public class Main {
    static int[][] dp;

    static int t(int n, int h) {
        if (dp[n][h] == -1) {
            int sum = 0;
            for (int m = 1; m <= n; m++) {
                int term1 = t(m - 1, h - 1);
                int innerSum1 = 0;
                for (int i = 0; i < h; i++) {
                    innerSum1 += t(n - m, i);
