                int innerSum2 = 0;
                for (int i = 0; i < h - 1; i++) {
                    innerSum2 += t(m - 1, i);
                }

                sum += term1 * innerSum1 + term2 * innerSum2;
            }
            dp[n][h] = sum;
        }
        return dp[n][h];
    }

