        int h = scanner.nextInt();

        int[][] dp = new int[n+1][n+1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }

        dp[0][0] = 1;

        int result = f(n, h, dp);
        System.out.println(result);
    }

    public static int f(int n, int h, int[][] dp) {
        if (dp[n][h] != -1) {
            return dp[n][h];
        }

        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            dp[n][h] = f(n, 1, dp);
            return dp[n][h];
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans += f(n-i-1, 0, dp) * f(i, h-1, dp);
            ans += f(n-i-1, h-1, dp) * f(i, 0, dp);
            ans -= f(n-i-1, h-1, dp) * f(i, h-1, dp);
        }

        dp[n][h] = ans;
        return ans;
    }
}

