public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        long[] s = new long[n + 1];
        long[] t = new long[n + 1];

        // Initialize s and t with 1s
        for (int i = 0; i <= n; i++) {
            s[i] = 1;
            t[i] = 1;
        }

        // Compute s values
        for (int m = 1; m <= n; m++) {
            long sum = 0;
            for (int k = 0; k < m; k++) {
                sum += s[m - 1 - k] * s[k];
            }
            s[m] = sum;
        }

        // Iterate h times to update t
        for (int j = 0; j < h; j++) {
            long[] newT = new long[n + 1];
            for (int m = 0; m <= n; m++) {
                long sum = 0;
                for (int k = 0; k < m; k++) {
                    sum += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
                }
                newT[m] = sum;
            }
            t = newT;
        }

        System.out.println(t[n]);
